 "content": "from collections import defaultdict


def _components(grid):
    h, w = len(grid), len(grid[0])
    counts = defaultdict(int)
    for row in grid:
        for v in row:
            counts[v] += 1
    background = max(counts, key=counts.get)
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == color and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, cells))
    return background, components


def _shape(cells):
    y0 = min(y for y, x in cells)
    x0 = min(x for y, x in cells)
    return tuple(sorted((y - y0, x - x0) for y, x in cells))


def transform(grid):
    out = [row[:] for row in grid]
    _, components = _components(grid)
    by_color = defaultdict(list)
    for color, cells in components:
        by_color[color].append(cells)

    # A single distinctive object supplies the replacement color.
    unique = [(len(parts[0]), color, parts[0])
              for color, parts in by_color.items() if len(parts) == 1]
    if not unique:
        return out
    _, key_color, key_cells = max(unique)
    key_y = sum(y for y, x in key_cells) / len(key_cells)
    key_x = sum(x for y, x in key_cells) / len(key_cells)

    # Find the largest repeated exact silhouette (translated copies); ties favor
    # non-linear shapes, since repeated straight strokes are background clutter.
    groups = defaultdict(list)
    for color, cells in components:
        if cells is key_cells:
            continue
        groups[_shape(cells)].append((color, cells))
    candidates = []
    for shape, items in groups.items():
        if len(items) < 2:
            continue
        n = len(shape)
        ys = {y for y, x in shape}
        xs = {x for y, x in shape}
        nonlinear = int(len(ys) > 1 and len(xs) > 1 and
                        not (len(ys) == 1 or len(xs) == 1))
        candidates.append((n, nonlinear, len(items), items))
    if not candidates:
        return out
    _, _, _, items = max(candidates, key=lambda z: (z[0], z[1], z[2]))
    # Of the duplicate silhouettes, recolor the one farthest from the key object.
    target_color, target = max(
        items,
        key=lambda item: sum((y-key_y)**2 + (x-key_x)**2 for y, x in item[1]) / len(item[1])
    )
    for y, x in target:
        out[y][x] = key_color
    return out


